get isInDST() {
  if (this.isOffsetFixed) {
    return false;
  } else {
    // The offset at the start of the year is the standard (non-DST) offset for most
    // zones, but not for all of them: in 1974, for example, DST in the US began on
    // January 6th, so January itself is not necessarily standard time. The smaller of
    // the offsets at the start of the year and in May is the standard offset in both
    // hemispheres.
    const standardOffset = Math.min(
      this.set({ month: 1, day: 1 }).offset,
      this.set({ month: 5, day: 1 }).offset
    );
    // DST can begin partway through a day (2am in the US), so count the whole of the
    // day on which DST begins as DST.
    const endOfDayOffset = this.set({
      hour: 23,
      minute: 59,
      second: 59,
      millisecond: 999
    }).offset;
    return this.offset > standardOffset || endOfDayOffset > standardOffset;
  }
}

